(window.__BOOKS=window.__BOOKS||{})["apelsiny"]={"b":[["h1","О сказке","about"],["p","«Любовь к трём апельсинам» (<i>L’amore delle tre melarance</i>) — первая сказка Гоцци; её сыграла труппа Сакки 25 января 1761 года. Полного текста пьесы Гоцци не оставил. Он напечатал «разбор по воспоминанию»: пересказ спектакля, где дословно даны только стихи и поединок мага <span class=\"ch\" data-ch=\"chelio\">Челио</span> с феей <span class=\"ch\" data-ch=\"morgana\">Морганой</span>. Сюжет — сказка Базиле «Три цитрона» («Сказка сказок», день V, 9)."],["p","Это пародия и спор о театре. Фея <span class=\"ch\" data-ch=\"morgana\">Моргана</span> — карикатура на аббата Кьяри, маг <span class=\"ch\" data-ch=\"chelio\">Челио</span> — на Гольдони; мартеллианские стихи у Гоцци — отрава, от которой гибнет принц, а лекарство от ипохондрии — смех масок. Абзацы, где Гоцци прямо говорит о Кьяри и Гольдони, отмечены на полях пометой «полемика»."],["p","В XX веке сказка прожила вторую жизнь: так назывался журнал Мейерхольда (1914–1916), и по ней Прокофьев написал оперу (1919, премьера — Чикаго, 1921)."],["h3","О примечаниях"],["p","Примечания со знаком [Комм.] составлены для этой полки по комментарию, приложенному к присланному тексту: факты взяты оттуда, изложение моё, короткие цитаты из комментария — в кавычках. Все примечания собраны и в конце книги."],["v","Пускай мой челн уносится теченьем,",0,1],["v","Пока его не опрокинет вал:",0,2],["v","Моей мечтой, моим воображеньем",0,3],["v","Я угодить бы каждому желал;",0,4],["v","Но в мире нет предела измененьям:",0,5],["v","Кто разность лиц и нравов сосчитал?",0,6],["v","Тот верен лилии, а этот — розе,",0,7],["v","У всех свой вкус, в поэзии и в прозе.",0,8],["v","Да, как Морганте, палицей своей","g",9],["v","Я, может быть, работал слишком рьяно.",0,10],["v","Но там, где есть достаточно судей,",0,11],["v","Рассудят дело поздно или рано.",0,12],["v","К тому ж увечье в разуме вещей,",0,13],["v","Когда врагом имеешь великана;",0,14],["v","И я брал меч, но меч не боевой:",0,15],["v","Игрою в жмурки был веселый бой.<a class=\"nr\" href=\"#n-n1\" data-n=\"n1\" aria-label=\"Примечание 1\">1</a>",0,16],["p","<i>Пульчи, «Морганте», песнь 27</i>","src"],["h1","Предисловие автора к пьесе «Любовь к трем апельсинам»","pref"],["p","«Любовь к трем Апельсинам» — детская сказка, превращенная мною в театральное представление, которым я начал оказывать поддержку труппе Сакки, — была лишь шутовской преувеличенной пародией на произведения синьоров Кьяри и Гольдони, бывшие в ходу в момент ее появления на свет."],["p","Единственной целью, которую я преследовал этой пьесой, было выяснить, насколько характер публики восприимчив к такому детски сказочному жанру на театральных подмостках. Из моего точного разбора по воспоминанию читатель убедится, что представление это было настолько смелым, что граничило даже с дерзостью. Истину никогда не следует скрывать. Никогда еще не было видано на сцене представления, совершенно лишенного серьезных ролей и целиком сотканного из общего шутовства всех персонажей, как это было в данном сценическом наброске. Пьеса была представлена труппой Сакки 25 января 1761 года, в театре Сан-Самуэле в Венеции, с прологом, помещаемым ниже перед разбором."],["p","Разъяренные приверженцы обоих поэтов сделали все возможное, чтобы обеспечить ее провал, но любезная публика поддержала ее целых семь представлений в течение карнавала, который уже приближался к концу."],["p","В последующие годы пьеса неизменно повторялась, но уже без преувеличенной пародии на вышеупомянутых поэтов, потому что для нее уже прошло время и она явилась бы некстати. Из моего разбора будет видно, чем она была при своем возникновении."],["h1","Пролог","prol"],["sp","Мальчик-вестник"],["dir","к зрителям"],["v","Мы, ваши слуги, старые актеры,",0,17],["v","Исполнены смущенья и стыда.",0,18],["v","Вся труппа там стоит, потупив взоры,",0,19],["v","И мрачны лица их, как никогда.",0,20],["v","Ведь в публике какие разговоры:",0,21],["v","Нас кормят вздором эти господа,",0,22],["v","Сплошным гнильем, комедией несвежей.",0,23],["v","Мошенники, насмешники, невежи!",0,24],["v","Клянусь природой, сотворившей нас:","g",25],["v","Чтоб зрителей вернуть благоволенье,",0,26],["v","Любой из них даст вырвать зуб и глаз.",0,27],["v","Да, таково их твердое решенье!",0,28],["v","Но, люди добрые, хоть этот раз",0,29],["v","На миг сдержите гневное волненье,",0,30],["v","Два слова дайте мне сказать — а там",0,31],["v","На вашу волю я себя отдам.",0,32],["v","Мы сбиты с толку: что же вас прельщает?","g",33],["v","Как угодить вам нашим ремеслом?",0,34],["v","Сегодня свистом публика встречает",0,35],["v","То, что вчера венчала торжеством.",0,36],["v","Непостижимый ветер управляет",0,37],["v","Общественного вкуса колесом.",0,38],["v","Одно мы знаем: чем полнее сборы,",0,39],["v","Тем лучше пьют и кушают актеры.",0,40],["v","Теперь закон, чтоб сцена каждый миг","g",41],["v","Кипела столь обильным водопадом",0,42],["v","Характеров, случайностей, интриг",0,43],["v","И происшествий, сыплющихся градом,",0,44],["v","Что страх невольный в душу нам проник",0,45],["v","И мы друг друга испытуем взглядом.",0,46],["v","Но так как надо что-нибудь жевать,",0,47],["v","Мы старым хламом мучим вас опять.",0,48],["v","Чем может быть объяснена утрата","g",49],["v","Приязни в ваших, зрители, сердцах",0,50],["v","К покорным слугам вашим, что когда-то",0,51],["v","Столь были чтимы в этих же стенах?",0,52],["v","Поэзия, не ты ли виновата?",0,53],["v","Пусть! Все равно! Все в этом мире прах,",0,54],["v","Мы претерпеть готовы все удары.",0,55],["v","Но ваша хладность горше всякой кары.",0,56],["v","Мы все предпримем с нашей стороны,","g",57],["v","Мы даже стать поэтами готовы.",0,58],["v","Чтоб воротить успехи старины,",0,59],["v","Решились мы искать венец лавровый.",0,60],["v","Мы на чернила выменим штаны,",0,61],["v","За десть бумаги плащ заложим новый,",0,62],["v","Что нет таланта, это не беда:",0,63],["v","Лишь были б вы довольны, господа.",0,64],["v","Великие, не виданные светом,","g",65],["v","Мы представлять комедии начнем.",0,66],["v","Где, как, когда мы их нашли, — об этом",0,67],["v","Не спрашивайте, да и что вам в том!",0,68],["v","Ведь если дождь прольется знойным летом,",0,69],["v","Его зовете новым вы дождем.",0,70],["v","А между тем я вам секрет открою:",0,71],["v","Вода есть дождь, дождь был всегда водою.",0,72],["v","Все движется, все — превращений ряд.","g",73],["v","Конечное становится исходным.",0,74],["v","Иной с портрета старого наряд",0,75],["v","Сегодня снова делается модным.",0,76],["v","Вкус, увлеченье, современный взгляд —",0,77],["v","Все милым делают и превосходным.",0,78],["v","И я клянусь: старейший театрал",0,79],["v","Таких комедий сроду не видал.",0,80],["v","У нас в руках сюжеты есть такие,","g",81],["v","Что превратят в младенцев стариков.",0,82],["v","Конечно, все родители честные",0,83],["v","К нам поведут сюда своих птенцов.",0,84],["v","Нас презрят лишь таланты неземные,",0,85],["v","Но это безразлично, — медяков",0,86],["v","Мы не расцениваем обоняньем:",0,87],["v","Чем отдают — невежеством иль знаньем.",0,88],["v","Нежданных происшествий длинный ряд","g",89],["v","Мы развернем пред вами в пестрой смене.",0,90],["v","Вас чудеса сегодня поразят,",0,91],["v","Каких никто не видывал на сцене.",0,92],["v","Ворота, птица, пес заговорят",0,93],["v","Стихами, что достойны восхвалений.",0,94],["v","Само собой, мартеллианский стих",0,95],["v","Понравится вам больше всех других.",0,96],["v","Актеры ждут, и, как пролог к картинам,","g",97],["v","Я должен вкратце изложить сюжет.",0,98],["v","Но я боюсь: шипением змеиным",0,99],["v","И громким криком будет ваш ответ.",0,100],["v","Итак, пойдет: «Любовь к трем Апельсинам».",0,101],["v","Я произнес. Мне отступленья нет.",0,102],["v","Теперь, друзья мои, вообразите,",0,103],["v","Что у огня вы с бабушкой сидите.",0,104],["sep",""],["p","Слишком очевидна сатира этого пролога, направленного против поэтов, притеснявших труппу актеров импровизированной комедии Сакки,<a class=\"nr\" href=\"#n-n2\" data-n=\"n2\" aria-label=\"Примечание 2\">2</a> которую я хотел поддержать, и слишком ясно мое намерение поставить на сцене ряд моих детских сказок, чтобы мне пришлось высказывать соображения по поводу отдельных мыслей, рассыпанных в самом прологе."],["p","В выборе первого сюжета, взятого из самой пустой сказки, какие рассказывают детям, в грубости диалогов, действия и характеров, намеренно опошленных, я хотел высмеять «Перекресток», «Кухарок», «Кьоджинские перепалки»<a class=\"nr\" href=\"#n-n3\" data-n=\"n3\" aria-label=\"Примечание 3\">3</a> и многие другие плебейские и тривиальнейшие произведения синьора Гольдони."],["h1","Действующие лица","dp"],["castrow","<span class=\"ch\" data-ch=\"silvio\">Сильвио</span>","король Треф<a class=\"nr\" href=\"#n-n4\" data-n=\"n4\" aria-label=\"Примечание 4\">4</a>","",""],["castrow","<span class=\"ch\" data-ch=\"tartaglia\">Тарталья</span>","принц, сын его","","маска"],["castrow","<span class=\"ch\" data-ch=\"clarice\">Клариче</span>","принцесса, племянница короля","",""],["castrow","<span class=\"ch\" data-ch=\"leandro\">Леандро</span>","валет Треф, первый министр","",""],["castrow","<span class=\"ch\" data-ch=\"pantalone\">Панталоне</span>","","pantalone-mask","Панталоне"],["castrow","<span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span>","","arlecchino-mask","Арлекин"],["castrow","<span class=\"ch\" data-ch=\"brighella\">Бригелла</span>","","","маска"],["castrow","<span class=\"ch\" data-ch=\"smeraldina\">Смеральдина</span>","арапка, служанка","colombina-mask","Коломбина"],["castrow","<span class=\"ch\" data-ch=\"chelio\">Челио</span>","маг","",""],["castrow","<span class=\"ch\" data-ch=\"morgana\">Моргана</span>","фея","",""],["castrow","Фарфарелло","дьявол","",""],["castrow","Дьявол с мехами","","",""],["castrow","<span class=\"ch\" data-ch=\"creonta\">Креонта</span>","великанша-волшебница","",""],["castrow","Три принцессы","дочери Конкула, короля Антиподов","",""],["castrow","Пес","","",""],["castrow","Веревка","","",""],["castrow","Ворота","","",""],["castrow","Пекарка","","",""],["castrow","<span class=\"ch\" data-ch=\"ninetta\">Голубка</span>","","",""],["castrow","Герольд","","",""],["castrow","Стража","","",""],["castrow","Придворные","","",""],["castrow","Народ","","",""],["place","Действие происходит в сказочном королевстве Треф."],["act","Действие первое","a1","I"],["p","Сильвио, король Треф, монарх воображаемого королевства, одежды которого в точности походили на одежды карточного короля, жаловался <span class=\"ch\" data-ch=\"pantalone\">Панталоне</span> на несчастие, постигшее его единственного сына, наследного принца <span class=\"ch\" data-ch=\"tartaglia\">Тарталью</span>, уже десять лет больного неизлечимой болезнью. Врачи определили ее как непреодолимое следствие ипохондрии и уже отступились от него. Король сильно плакал. <span class=\"ch\" data-ch=\"pantalone\">Панталоне</span>, осмеивая врачей, указывал на удивительные секреты некоторых живших в то время шарлатанов. Король возражал, что все было уже испробовано без пользы. <span class=\"ch\" data-ch=\"pantalone\">Панталоне</span>, фантазируя о происхождении болезни, спрашивал короля по секрету, чтобы его не услышала окружавшая монарха стража, не приобрел ли его величество в молодости какой-нибудь болезни, которая, перейдя в кровь наследного принца, привела его к этому несчастью, и не поможет ли в данном случае ртуть. Король со всей серьезностью уверял, что он всегда был верен королеве. <span class=\"ch\" data-ch=\"pantalone\">Панталоне</span> добавлял, что принц, быть может, скрывает из стыда какую-нибудь приобретенную им заразную болезнь. Король серьезно и величественно уверял, что он своим отеческим осмотром удостоверился, что это не так и что болезнь его сына — не что иное, как смертельное последствие ипохондрии; врачи определили, что если он не засмеется, то вскоре будет в гробу, ибо только смех может быть очевидным знаком его исцеления. Но это невозможно! Он добавлял, что его печалит видеть себя уже дряхлым, с единственным умирающим сыном и с племянницей, принцессой <span class=\"ch\" data-ch=\"clarice\">Клариче</span>, будущей наследницей его королевства, девушкой своевольной, странной и жестокой. Он жалел своих подданных и плакал навзрыд, забыв о своем королевском величии. <span class=\"ch\" data-ch=\"pantalone\">Панталоне</span> утешал его; он высказывал соображение, что если исцеление принца <span class=\"ch\" data-ch=\"tartaglia\">Тартальи</span> зависит от его смеха, то не следует держать двор в такой печали. Пусть будут объявлены празднества: игры, маскарады и спектакли. Нужно разрешить <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span>, человеку заслуженному в искусстве смеха, настоящему рецепту против ипохондрии, говорить с принцем. <span class=\"ch\" data-ch=\"pantalone\">Панталоне</span> заметил у принца некоторую склонность доверять <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span>. Может случиться, что принц засмеется и выздоровеет. Король соглашался с этим и собирался отдать соответствующие распоряжения."],["p","Выходил <span class=\"ch\" data-ch=\"leandro\">Леандро</span>, валет Треф, первый министр. Это лицо было точно так же одето, как его фигура в игральных картах, <span class=\"ch\" data-ch=\"pantalone\">Панталоне</span> высказывал в сторону свое подозрение о предательстве <span class=\"ch\" data-ch=\"leandro\">Леандро</span>. Король заказывал <span class=\"ch\" data-ch=\"leandro\">Леандро</span> празднества, игры и вакханалии. Он говорил, что всякий, кому удастся рассмешить принца, получит большую награду. <span class=\"ch\" data-ch=\"leandro\">Леандро</span> отговаривал короля от такого решения, полагая, что все это еще больше повредит больному. <span class=\"ch\" data-ch=\"pantalone\">Панталоне</span> настаивал на своем совете. Король снова подтверждал свои приказания и уходил. <span class=\"ch\" data-ch=\"pantalone\">Панталоне</span> ликовал. Он говорил в сторону, что, по его мнению, <span class=\"ch\" data-ch=\"leandro\">Леандро</span> желает смерти принца. Затем он следовал за королем. <span class=\"ch\" data-ch=\"leandro\">Леандро</span> оставался в смущении. Он видел какое-то противодействие своему желанию, но не мог понять его причину."],["p","Выходила принцесса <span class=\"ch\" data-ch=\"clarice\">Клариче</span>, племянница короля. Никогда еще не было видано на сцене принцессы с таким странным, капризным и решительным нравом. Я очень благодарен синьору Кьяри, который в своих произведениях дал мне несколько образцов для преувеличенной пародии характеров.","pol"],["p","Клариче, уговорившись с <span class=\"ch\" data-ch=\"leandro\">Леандро</span> выйти за него замуж и возвести его на престол, если она останется наследницей королевства в случае смерти ее двоюродного брата <span class=\"ch\" data-ch=\"tartaglia\">Тартальи</span>, бранила <span class=\"ch\" data-ch=\"leandro\">Леандро</span> за равнодушие, которое он проявлял, выжидая, пока ее кузен умрет от такой длительной болезни, как ипохондрия. <span class=\"ch\" data-ch=\"leandro\">Леандро</span> оправдывался с осторожностью, говоря, что его покровительница, фея <span class=\"ch\" data-ch=\"morgana\">Моргана</span>, вручила ему несколько грамот в мартеллианских стихах, чтобы он дал их <span class=\"ch\" data-ch=\"tartaglia\">Тарталье</span> запеченными в хлебе; это должно привести его к медленной смерти от последствий ипохондрии. Так говорилось для того, чтобы осудить произведения синьора Кьяри и синьора Гольдони, которые, будучи написаны мартеллианскими стихами, утомляли однообразием рифм.<a class=\"nr\" href=\"#n-n5\" data-n=\"n5\" aria-label=\"Примечание 5\">5</a> Фея <span class=\"ch\" data-ch=\"morgana\">Моргана</span> была врагом короля Треф, так как потеряла много денег, ставя на портрет этого короля, и, напротив, была другом валета Треф, ибо несколько отыгралась на его изображении. Она жила в озере поблизости от города. Арапка <span class=\"ch\" data-ch=\"smeraldina\">Смеральдина</span>,<a class=\"nr\" href=\"#n-n6\" data-n=\"n6\" aria-label=\"Примечание 6\">6</a> которая играла роль служанки в этой сценической пародии, была посредницей между <span class=\"ch\" data-ch=\"leandro\">Леандро</span> и <span class=\"ch\" data-ch=\"morgana\">Морганой</span>. <span class=\"ch\" data-ch=\"clarice\">Клариче</span> приходила в ярость, услышав о медленном способе, который применялся для умерщвления <span class=\"ch\" data-ch=\"tartaglia\">Тартальи</span>. <span class=\"ch\" data-ch=\"leandro\">Леандро</span> высказывал сомнения о пользе грамот в мартеллианских стихах. Он видел, как прибыл ко двору, неизвестно кем посланный, некто <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span>, забавная личность. Если <span class=\"ch\" data-ch=\"tartaglia\">Тарталья</span> засмеется, он выздоровеет. <span class=\"ch\" data-ch=\"clarice\">Клариче</span> приходила в сильное беспокойство: она видела этого <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span>; невозможно было удержаться от смеха при одном взгляде на него. Грамоты в мартеллианских стихах, даже отпечатанные самым жирным шрифтом, будут бесполезны. В этих рассуждениях читатель увидит защиту импровизированной комедии масок как средства против последствий ипохондрии, в противовес меланхолическим писаниям тогдашних поэтов. <span class=\"ch\" data-ch=\"leandro\">Леандро</span> уже раньше послал своего гонца <span class=\"ch\" data-ch=\"brighella\">Бригеллу</span> к арапке <span class=\"ch\" data-ch=\"smeraldina\">Смеральдине</span> с целью узнать, что означает тайна появления этого <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span>, а также просить о помощи.","pol"],["p","Выходил <span class=\"ch\" data-ch=\"brighella\">Бригелла</span> и таинственно сообщал, что <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> прислан ко двору неким магом <span class=\"ch\" data-ch=\"chelio\">Челио</span>, врагом <span class=\"ch\" data-ch=\"morgana\">Морганы</span> и покровителем короля Треф, по причинам, сходным с указанными выше. <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> служил лекарством против последствий ипохондрии, вызванной грамотами в мартеллианских стихах, и прибыл ко двору, чтобы охранять короля, его сына и всех обитателей города от заразной болезни, распространяемой этими грамотами."],["p","Следует заметить, что во вражде феи <span class=\"ch\" data-ch=\"morgana\">Морганы</span> и мага <span class=\"ch\" data-ch=\"chelio\">Челио</span> аллегорически изображались театральные битвы, происходившие между синьорами Гольдони и Кьяри, и что в лице феи и мага изображались в преувеличенной пародии оба поэта. Фея <span class=\"ch\" data-ch=\"morgana\">Моргана</span> представляла карикатуру на синьора Кьяри, а маг <span class=\"ch\" data-ch=\"chelio\">Челио</span> — карикатуру на синьора Гольдони.","pol"],["p","Принесенное <span class=\"ch\" data-ch=\"brighella\">Бригеллой</span> известие о <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> приводило <span class=\"ch\" data-ch=\"clarice\">Клариче</span> и <span class=\"ch\" data-ch=\"leandro\">Леандро</span> в большое смущение. Они обсуждали разные способы погубить <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span>. <span class=\"ch\" data-ch=\"clarice\">Клариче</span> советовала мышьяк или пулю, <span class=\"ch\" data-ch=\"leandro\">Леандро</span> — мартеллианские стихи в хлебе или опий. <span class=\"ch\" data-ch=\"clarice\">Клариче</span> возражала, что мартеллианские стихи и опий вещи сходные, но <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> кажется ей обладающим достаточно крепким желудком, чтобы переварить подобные снадобья. <span class=\"ch\" data-ch=\"brighella\">Бригелла</span> добавлял, что <span class=\"ch\" data-ch=\"morgana\">Моргана</span>, узнав о празднествах, готовившихся для развлечения принца, чтобы заставить его рассмеяться, обещала прийти на торжество и противопоставить его здоровому смеху проклятие, которое сведет принца в могилу. <span class=\"ch\" data-ch=\"clarice\">Клариче</span> уходила, чтобы дать место приготовлениям к заказанным зрелищам, а <span class=\"ch\" data-ch=\"leandro\">Леандро</span> и <span class=\"ch\" data-ch=\"brighella\">Бригелла</span> уходили, чтобы распорядиться ими."],["p","Действие переносилось в комнату принца, больного ипохондрией. Этот шутовской принц <span class=\"ch\" data-ch=\"tartaglia\">Тарталья</span> был наряжен в самый забавный костюм больного. Он сидел в большом кресле, а возле него находился столик, о который он опирался, заставленный склянками, мазями, плевательницами и другими предметами, соответствующими его состоянию. Слабым голосом он жаловался на свою несчастную судьбу, рассказывал о способах лечения, которым он напрасно подвергался, говорил о странных симптомах своей неизлечимой болезни. И хотя он имел только краткое изложение сцены, этот превосходный актер разыгрывал ее с невиданным блеском и разнообразием. Его шутовская и в то же время естественная речь все время вызывала дружные взрывы хохота у зрителей."],["p","Затем выходил пресмешной <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> и делал попытку развеселить больного. Импровизированная сцена, разыгранная по сценарию этими двумя отличнейшими комиками, не могла не получиться чрезвычайно веселой. Принц благосклонно смотрел на проделки <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span>, но, сколько тот ни пробовал, он не мог рассмешить принца. Принц возобновлял разговор о своей болезни и хотел узнать о ней мнение <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span>. <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> произносил запутанные комические рассуждения на медицинские темы, самые забавные, какие когда-либо приходилось слышать. Он нюхал дыхание принца, слышал запах от переполнения его желудка непереваренными мартеллианскими стихами. Принц кашлял и хотел плюнуть. <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> подставлял ему чашку и исследовал его плевок; находил в нем гнилые и вонючие рифмы. Эта сцена продолжалась около двадцати минут при непрерывном смехе зрителей."],["p","Слышались звуки инструментов, которые давали сигнал к началу веселых зрелищ, происходивших на большом дворе королевского дворца. <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> хотел повести принца на крытую террасу, чтобы оттуда смотреть на них. Принц восклицал, что это невозможно. Завязывался смешной спор. <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> в ярости выбрасывал в окно склянки, чашки и другие предметы, служившие <span class=\"ch\" data-ch=\"tartaglia\">Тарталье</span> во время его болезни. Последний громко кричал и плакал, как ребенок. Наконец <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> уносил принца насильно, взвалив его себе на плечи; при этом <span class=\"ch\" data-ch=\"tartaglia\">Тарталья</span> выл так, как если бы у него выпускали кишки."],["p","Далее открывалась сцена в большом дворе королевского дворца. <span class=\"ch\" data-ch=\"leandro\">Леандро</span> сообщал, что он исполнил приказания относительно зрелищ, что весь народ, печальный и жаждущий смеха, надел маски и собрался в этот двор на праздник, но что он из предосторожности заставил многих лиц замаскироваться мрачными фигурами, чтобы увеличить меланхолию принца, который будет смотреть на них."],["p","Уже настало время открыть ворота и дать народу возможность войти."],["p","Выходила <span class=\"ch\" data-ch=\"morgana\">Моргана</span>, принявшая образ карикатурной старушонки. <span class=\"ch\" data-ch=\"leandro\">Леандро</span> удивлялся, как подобное существо могло проникнуть сквозь запертые двери."],["p","<span class=\"ch\" data-ch=\"morgana\">Моргана</span> открывалась ему и говорила, что пришла сюда в этом виде с целью окончательно погубить принца. Она прибавляла, что уже пора начать празднество. <span class=\"ch\" data-ch=\"leandro\">Леандро</span> благодарил ее, называл ее царицей ипохондрии. <span class=\"ch\" data-ch=\"morgana\">Моргана</span> удалялась."],["p","Открывались ворота двора. На крытой террасе фасада появлялись король <span class=\"ch\" data-ch=\"silvio\">Сильвио</span>, меланхолический принц <span class=\"ch\" data-ch=\"tartaglia\">Тарталья</span>, закутанный в шубу, Клариче, Панталоне, стража. Зрелище и празднества были именно те, о каких рассказывают детям в сказке о трех Апельсинах."],["p","Входил народ. Происходил конный турнир. <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> в качестве начальника отряда заставлял участвовавших в состязании проделывать смешные движения. При этом каждый раз, оборачиваясь к террасе, он спрашивал у его величества, смеется ли принц. Но принц плакал, жалуясь, что воздух его беспокоит, а шум вызывает головную боль, и просил короля, чтобы тот приказал отнести его в теплую постель."],["p","У двух фонтанов, из которых один источал масло, а другой вино, толпился народ, делая себе запасы. Происходили вульгарнейшие простонародные перебранки, но ничто не могло заставить принца рассмеяться."],["p","Выходила <span class=\"ch\" data-ch=\"morgana\">Моргана</span> в виде старушонки с кувшином в руках, чтобы запастись маслом из фонтана. <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> осыпал старушонку градом оскорблений. Она падала, высоко задрав ноги. Все эти пошлости, сопровождавшие представление обыкновенной сказки, развлекали зрителей своей новизной не меньше, чем «Кухарки», «Перекресток», «Кьоджинские перепалки» и другие пошлые произведения синьора Гольдони.","pol"],["p","При виде падения старушонки принц разражался долгим и звонким смехом и разом излечивался от всех своих недугов. <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> получал награду, а зрители, избавленные наконец от тяжелого впечатления его болезни, хохотали во все горло."],["p","Весь двор радовался происшедшему. Только <span class=\"ch\" data-ch=\"leandro\">Леандро</span> и <span class=\"ch\" data-ch=\"clarice\">Клариче</span> были грустны. Разъяренная <span class=\"ch\" data-ch=\"morgana\">Моргана</span>, поднявшись с земли, с жаром упрекала принца и бросала ему в лицо следующее ужасное проклятье в стиле Кьяри:","pol"],["v","Отверзи слух, чудовище! Дойди мой крик до чрева.",0,105],["v","Сквозь стен, сквозь гор препятствие проникнет голос гнева.",0,106],["v","Как гибельная молния испепеляет сушу,",0,107],["v","Так пусть мои вещания тебе вонзятся в душу.",0,108],["v","Как на буксире лодочка за кораблем уходит,",0,109],["v","Так пусть тебя проклятие повсюду за нос водит.",0,110],["v","Да сгинешь ты от грозного проклятия <span class=\"ch\" data-ch=\"morgana\">Морганы</span>,",0,111],["v","Как в море травоядное, как рыба средь поляны.",0,112],["v","Плутон — властитель Тартара, и Пиндар, вверх парящий,<a class=\"nr\" href=\"#n-n7\" data-n=\"n7\" aria-label=\"Примечание 7\">7</a>",0,113],["v","К трем Апельсинам страстию тебя сожгут палящей.",0,114],["v","Мольбой, угрозой, жалобой не тронется судьбина:",0,115],["v","Спеши на страшный промысел — искать три Апельсина!",0,116],["p","<span class=\"ch\" data-ch=\"morgana\">Моргана</span> исчезала. Принц внезапно воодушевлялся любовью к трем Апельсинам. Его уводили при сильнейшем смущении всего двора. Какой вздор!"],["p","Какое огорчение для обоих поэтов! Так кончался первый акт сказки при громких аплодисментах всей публики.","pol"],["act","Действие второе","a2","II"],["p","<span class=\"ch\" data-ch=\"pantalone\">Панталоне</span> в одной из комнат принца, в отчаянии и вне себя, рассказывал о тяжелом состоянии <span class=\"ch\" data-ch=\"tartaglia\">Тартальи</span>, которым овладело бешенство вследствие произнесенного над ним проклятия. Успокоить его было немыслимо. Он требовал от отца пару подбитых железом башмаков, чтобы отправиться бродить по свету до тех пор, пока он не найдет роковые Апельсины, предмет своей любви."],["p","<span class=\"ch\" data-ch=\"pantalone\">Панталоне</span> получил приказ, под страхом немилости, просить у короля эти башмаки. Положение было очень серьезным. Такой сюжет очень подходил для театра. <span class=\"ch\" data-ch=\"pantalone\">Панталоне</span> высмеивал по этому поводу, в шутливой форме, сюжеты, бывшие тогда в ходу. Наконец он уходил к королю."],["p","Выходили одержимый манией принц <span class=\"ch\" data-ch=\"tartaglia\">Тарталья</span> и <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span>. Принц выражал нетерпение по поводу задержки с железными башмаками. <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> задавал нелепые вопросы. Принц объявлял, что хочет отправиться искать три Апельсина, которые, как ему рассказывала его бабушка, находятся за две тысячи миль во власти волшебницы-великанши <span class=\"ch\" data-ch=\"creonta\">Креонты</span>. Он требовал свои доспехи и приказывал <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> вооружиться, так как хотел иметь его своим оруженосцем."],["p","Следовала шутовская сцена между этими всегда забавными персонажами. Они надевали кольчуги и шлемы и брали большие длинные мечи; все это они делали с величайшей карикатурностью."],["p","Выходили король <span class=\"ch\" data-ch=\"silvio\">Сильвио</span>, <span class=\"ch\" data-ch=\"pantalone\">Панталоне</span> и стража. Один из стражей нес в тазу пару железных башмаков."],["p","Эта сцена проводилась четырьмя персонажами с преувеличенной важностью, делавшей ее вдвойне смешной. С трагическим и драматическим величием отец пытался отговорить сына от его опасного предприятия. Он просил, угрожал, впадал в патетический тон. Одержимый манией принц настаивал на своем. Он был уверен, что снова впадет в ипохондрию, если ему не позволят исполнить его намерение, и в конце концов доходил до грубых угроз по адресу отца."],["p","Огорченный король не знал, что ответить. Он делал заключение, что неуважение к нему сына объясняется тем, что он насмотрелся новых комедий. И действительно, мы видели в одной пьесе синьора Кьяри, как сын обнажал шпагу, чтобы убить собственного отца. Подобными примерами изобиловали тогдашние комедии, высмеянные мною в этой глупой сказке. Принц никак не мог успокоиться, пока <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> не надевал ему железные башмаки. Сцена заканчивалась квартетом в драматических стихах, состоявших из причитаний, прощаний и вздохов. Принц <span class=\"ch\" data-ch=\"tartaglia\">Тарталья</span> и <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> отправлялись в путь.","pol"],["p","Король падал на кресло в обмороке. <span class=\"ch\" data-ch=\"pantalone\">Панталоне</span> громко требовал уксуса, чтобы ему помочь. Прибегали <span class=\"ch\" data-ch=\"clarice\">Клариче</span>, <span class=\"ch\" data-ch=\"leandro\">Леандро</span> и <span class=\"ch\" data-ch=\"brighella\">Бригелла</span>, бранили <span class=\"ch\" data-ch=\"pantalone\">Панталоне</span> за производимый им шум. <span class=\"ch\" data-ch=\"pantalone\">Панталоне</span> говорил, что речь идет о короле, лежащем в обмороке, и принце, который пошел на гибель для трудного приобретения Апельсинов. <span class=\"ch\" data-ch=\"brighella\">Бригелла</span> возражал, что это такой же вздор, как новые комедии, переворачивающие все вверх дном без всякого смысла. Между тем король, придя в себя, с преувеличенным трагизмом оплакивал сына, как мертвого. Он отдавал приказ всему двору облачиться в траурные одежды, сам же уходил, чтобы запереться в кабинете и там окончить свои дни под бременем скорби. <span class=\"ch\" data-ch=\"pantalone\">Панталоне</span> клялся разделить печаль короля, смешать в одном носовом платке их общие слезы и дать современным поэтам сюжет для нескончаемых эпизодов в мартеллианских стихах. После этого он следовал за королем."],["p","Клариче, <span class=\"ch\" data-ch=\"leandro\">Леандро</span> и <span class=\"ch\" data-ch=\"brighella\">Бригелла</span> радостно восхваляли <span class=\"ch\" data-ch=\"morgana\">Моргану</span>. Капризная <span class=\"ch\" data-ch=\"clarice\">Клариче</span> хотела, прежде чем возвести <span class=\"ch\" data-ch=\"leandro\">Леандро</span> на престол, заключить соглашение о своем праве распоряжаться в королевстве. В военное время она желала стоять во главе войск. Даже в случае поражения она сумеет очаровать своей красотой вражеского полководца. Когда же тот влюбится и будет ею обнадежен, она при его приближении воткнет ему нож в живот. Это была язвительная насмешка над «Аттилой» синьора Кьяри. Кроме того, <span class=\"ch\" data-ch=\"clarice\">Клариче</span> хотела иметь право раздавать придворные должности. <span class=\"ch\" data-ch=\"brighella\">Бригелла</span> просил за свои заслуги должность управляющего королевскими зрелищами.","pol"],["p","Следовал спор по вопросу о выборе рода театральных развлечений. <span class=\"ch\" data-ch=\"clarice\">Клариче</span> требовала трагических представлений, в которых действующие лица бросались бы из окон и с башен, не сломав себе шеи, и происходили бы другие столь же удивительные происшествия, — одним словом, она требовала произведений синьора Кьяри. <span class=\"ch\" data-ch=\"leandro\">Леандро</span> предпочитал комедии характеров, иначе говоря — произведения синьора Гольдони. <span class=\"ch\" data-ch=\"brighella\">Бригелла</span> предлагал импровизированную комедию масок, которая может служить невинным развлечением для народа.<a class=\"nr\" href=\"#n-n8\" data-n=\"n8\" aria-label=\"Примечание 8\">8</a> <span class=\"ch\" data-ch=\"clarice\">Клариче</span> и <span class=\"ch\" data-ch=\"leandro\">Леандро</span> возражали в гневе, что не хотят глупых буффонад, недостойных просвещенного века, и уходили.","pol"],["p","<span class=\"ch\" data-ch=\"brighella\">Бригелла</span> произносил патетическую речь, соболезнуя актерской труппе Сакки, правда, не называя ее по имени, но так, что легко было понять, кого он имел в виду. Он оплакивал почтенных и заслуженных актеров, притесняемых со всех сторон и потерявших любовь той публики, которую они обожают и для которой они столько времени служили развлечением. После этого он уходил под аплодисменты зрителей, превосходно понявших истинный смысл его речи."],["p","Далее открывалась сцена в пустыне. Было видно, как маг <span class=\"ch\" data-ch=\"chelio\">Челио</span>, покровитель принца <span class=\"ch\" data-ch=\"tartaglia\">Тартальи</span>, чертил круги. Он вызывал дьявола Фарфарелло."],["p","Выходил дьявол Фарфарелло и страшным голосом говорил мартеллианскими стихами следующее:"],["v","В чем дело? Кто зовет меня из преисподней щели?",0,117],["v","Ты кто: ты театральный маг иль маг на самом деле?",0,118],["v","А если театральный ты, ты сам того же мненья,",0,119],["v","Что старый хлам все дьяволы, волхвы и привиденья.",0,120],["p","Оба поэта несколько раз заявляли, что хотят уничтожить в комедиях маски, магов и дьяволов."],["p","<span class=\"ch\" data-ch=\"chelio\">Челио</span> отвечал прозой, что он настоящий маг. Дьявол добавлял:"],["v","Ну, ладно, будь кем вздумаешь; но только магам ложным",0,121],["v","Пристало говорить стихом четырнадцатисложным.",0,122],["p","<span class=\"ch\" data-ch=\"chelio\">Челио</span> грозил дьяволу — он хотел говорить прозой по своему разумению. Он спрашивал, добился ли какого-нибудь результата <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span>, посланный им ко двору короля Треф; заставил ли он рассмеяться <span class=\"ch\" data-ch=\"tartaglia\">Тарталью</span>, и излечился ли тот от своей ипохондрии. Дьявол отвечал:"],["v","Захохотал и стал здоров. Но силой заклинанья",0,123],["v","Моргана, фея злобная, сгубила все старанья.",0,124],["v","И, задыхаясь, в ярости, отца и двор покинув,",0,125],["v","Пустился принц на поиски заветных Апельсинов.",0,126],["v","Он с <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> близится. За ними вслед пустила",0,127],["v","<span class=\"ch\" data-ch=\"morgana\">Моргана</span> беса хмурого, чтоб поддувал им с тыла.",0,128],["v","Миль отмахавши с тысячу, они в конце дороги",0,129],["v","И здесь, в стенах волшебницы, протянут скоро ноги.",0,130],["p","Дьявол Фарфарелло исчезал. <span class=\"ch\" data-ch=\"chelio\">Челио</span> выкрикивал проклятия по адресу своего врага <span class=\"ch\" data-ch=\"morgana\">Морганы</span>. Он разъяснял великую опасность, которой подвергались <span class=\"ch\" data-ch=\"tartaglia\">Тарталья</span> и <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span>, отправившись в лежащий недалеко от этого места замок <span class=\"ch\" data-ch=\"creonta\">Креонты</span>, где хранились три роковые Апельсина. Он удалялся, чтобы приготовить все необходимое для спасения двух заслуженных и чрезвычайно полезных обществу лиц."],["p","Маг <span class=\"ch\" data-ch=\"chelio\">Челио</span>, который изображал в этом вздоре синьора Гольдони, не должен был бы защищать <span class=\"ch\" data-ch=\"tartaglia\">Тарталью</span> и <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span>. Эта ошибка вполне достойна порицания, если может заслуживать порицания такая чертовщина, как этот сценический набросок. Синьоры Кьяри и Гольдони были в то время врагами в своем поэтическом творчестве. Я хотел в лице <span class=\"ch\" data-ch=\"morgana\">Морганы</span> и <span class=\"ch\" data-ch=\"chelio\">Челио</span> вывести в карикатурном виде противоположность этих двух талантов, но вместе с тем я старался не удваивать число действующих лиц, чтобы спастись от упреков в чрезмерности своего каприза.","pol"],["p","На сцену выходили принц <span class=\"ch\" data-ch=\"tartaglia\">Тарталья</span> и <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span>, вооруженные, как было указано выше. Они выбегали стремительно быстро. За ними следовал дьявол с мехами, который, поддувая им в спину, заставлял их двигаться с необычайной быстротой. Внезапно дьявол с мехами переставал дуть и исчезал. От прекращения ветра оба путешественника падали на землю, не будучи в состоянии остановиться."],["p","Я бесконечно обязан синьору Кьяри за превосходное впечатление, которое производила эта дьявольская пародия.","pol"],["p","В своих драмах, заимствованных из «Энеиды»,<a class=\"nr\" href=\"#n-n9\" data-n=\"n9\" aria-label=\"Примечание 9\">9</a> он заставлял троянцев на протяжении одной пьесы проделывать огромнейшие путешествия без помощи моего дьявола с мехами."],["p","Этот писатель, педантично нападавший на всех других за различные неправильности, сам позволял себе всевозможные вольности. Я видел в его «Эццелине, тиране Падуанском», как в одной сцене был покорен Эццелин и отправлен полководец для захвата Тревизо, находившегося еще под властью тирана. В следующей сцене того же акта полководец уже возвращался с победой."],["p","Он сделал больше тридцати миль, взял Тревизо, казнил притеснителей и в цветистой речи, которую он произносил, оправдывал совершенные им невероятные поступки доблестью своего отважного скакуна."],["p","<span class=\"ch\" data-ch=\"tartaglia\">Тарталья</span> и <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> должны были проделать две тысячи миль, чтобы достичь замка <span class=\"ch\" data-ch=\"creonta\">Креонты</span>. Мой дьявол с мехами оправдывал их путешествие лучше лошади синьора аббата Кьяри. Оба эти забавнейших персонажа в удивлении вставали с земли, ошеломленные ветром, дувшим на них сзади. Они делали нелепое географическое описание тех стран, рек и морей, которые прошли. Из того, что ветер прекратился, <span class=\"ch\" data-ch=\"tartaglia\">Тарталья</span> выводил заключение, что три Апельсина недалеко. <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> запыхался; он был голоден; он спрашивал принца, захватил ли тот с собой достаточный запас денег или векселей. <span class=\"ch\" data-ch=\"tartaglia\">Тарталья</span> презирал все эти низкие и бесполезные вопросы. Он замечал неподалеку замок на горе и полагал, что это замок <span class=\"ch\" data-ch=\"creonta\">Креонты</span>, хранительницы Апельсинов. Он отправлялся в путь, а <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> следовал за ним, надеясь найти пищу.","pol"],["p","Выходил маг <span class=\"ch\" data-ch=\"chelio\">Челио</span>, пугал обоих и напрасно старался отговорить принца от опасного предприятия. Он описывал непреодолимые препятствия — те самые, которые рассказывают детям в этой сказке; но <span class=\"ch\" data-ch=\"chelio\">Челио</span> говорил о них, вытаращив глаза, страшным голосом, как если бы они были великими вещами. Опасности заключались в железных Воротах, покрытых ржавчиной от времени, в голодном Псе, в Веревке от колодца, полусгнившей от сырости, в Пекарке, которая, не имея метлы, подметала печь собственными грудями. Принц, нисколько не устрашенный этими ужасными предметами, хотел идти в замок. Видя его решимость, маг <span class=\"ch\" data-ch=\"chelio\">Челио</span> давал ему волшебную мазь, чтобы смазать засов на Воротах, кусок хлеба, чтобы бросить его голодному Псу, и пучок вереска для Пекарки, подметающей печь собственными грудями. Он напоминал им о том, чтобы они вытащили Веревку из сырости и высушили ее на солнце. Он прибавлял, что если по счастливой случайности им удастся похитить три охраняемых Апельсина, им следует тотчас же бежать из замка и помнить, что нельзя разрезать ни одного из этих Апельсинов иначе, как возле какого-нибудь источника. Он обещал, в случае если после похищения они уйдут невредимыми от опасности, прислать им того же дьявола с мехами, который, дуя им в спину, перенесет их в несколько мгновений на родину. Поручив их покровительству неба, маг <span class=\"ch\" data-ch=\"chelio\">Челио</span> уходил."],["p","<span class=\"ch\" data-ch=\"tartaglia\">Тарталья</span> и <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> направлялись с полученными предметами к замку."],["p","Тут опускалась занавеска, изображавшая дворец короля Треф. Какое нарушение всех правил! Что за неуместная критика! Следовали две небольшие сцены: первая между арапкой <span class=\"ch\" data-ch=\"smeraldina\">Смеральдиной</span> и <span class=\"ch\" data-ch=\"brighella\">Бригеллой</span>, радовавшимися гибели <span class=\"ch\" data-ch=\"tartaglia\">Тартальи</span>; вторая с феей <span class=\"ch\" data-ch=\"morgana\">Морганой</span>, которая в гневе приказывала <span class=\"ch\" data-ch=\"brighella\">Бригелле</span> известить <span class=\"ch\" data-ch=\"clarice\">Клариче</span> и <span class=\"ch\" data-ch=\"leandro\">Леандро</span> о том, что <span class=\"ch\" data-ch=\"chelio\">Челио</span> помогает <span class=\"ch\" data-ch=\"tartaglia\">Тарталье</span> в его предприятии. Она получила эти сведения от демона Драгинаццо. <span class=\"ch\" data-ch=\"morgana\">Моргана</span> приказывала <span class=\"ch\" data-ch=\"smeraldina\">Смеральдине</span> следовать за нею до ее озера, куда должны будут попасть <span class=\"ch\" data-ch=\"tartaglia\">Тарталья</span> и <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span>, если они выйдут живыми из рук <span class=\"ch\" data-ch=\"creonta\">Креонты</span>."],["p","Здесь она сможет устроить им новые козни. Все расходились в смущении."],["p","Далее сцена открывалась во дворе замка <span class=\"ch\" data-ch=\"creonta\">Креонты</span>."],["p","Уже с самого начала этой сцены, в которой разные нелепые предметы выступали в качестве действующих лиц, я имел возможность убедиться в том могучем воздействии, какое производит на людей все чудесное."],["p","Ворота с железной решеткой на заднем плане; голодный Пес, бегавший взад и вперед с громким воем; колодец с лежавшей рядом Веревкой; Пекарка, подметавшая печь двумя огромнейшими грудями, — держали весь театр в напряженном внимании, нисколько не меньше, чем лучшие сцены из произведений обоих наших поэтов.","pol"],["p","Было видно, как за решеткой принц <span class=\"ch\" data-ch=\"tartaglia\">Тарталья</span> и <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> старались смазать ее засовы волшебной мазью, после чего Ворота распахивались. Вот так диво!"],["p","Они входили. Пес с лаем набрасывался на них. Они кидали ему хлеб, он успокаивался. Вот так чудо!"],["p","В то время как <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span>, полный страхов, раскладывал Веревку на солнце и давал Пекарке веник, принц входил в замок и затем радостно выходил из него, похитив три огромных Апельсина."],["p","Великие происшествия на этом не кончались. Солнце меркло, земля содрогалась, слышались сильные удары грома. Принц передавал Апельсины дрожащему <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span>; они приготовлялись к бегству. Из замка раздавался ужасающий голос <span class=\"ch\" data-ch=\"creonta\">Креонты</span>, которая в точном соответствии с текстом детской сказки кричала следующим образом:"],["v","Пекарочка, Пекарочка, избавь меня от срама.",0,131],["v","Хватай обоих за ноги и в печь швыряй их прямо!",0,132],["p","Пекарка, точно следуя тексту, отвечала:"],["v","Ну, нет! Я столько времени, и месяцы и годы,",0,133],["v","Терзаю груди белые, переношу невзгоды.",0,134],["v","Ты для меня, жестокая, метлу и то жалела,",0,135],["v","А эти веник дали мне. Пускай уходят смело.",0,136],["p","<span class=\"ch\" data-ch=\"creonta\">Креонта</span> кричала:"],["v","Веревка, удави ты их!",0,137],["p","А Веревка отвечала ей по тексту:"],["v","Злодейка, ты забыла,",0,138],["v","Как много лет и месяцев меня ты здесь морила,",0,139],["v","В грязи держала, в сырости, в забвении убогом.",0,140],["v","Они мне дали высохнуть. Пускай уходят с богом.",0,141],["p","Креонта, продолжая придерживаться текста сказки, вопила:"],["v","Мой Пес, мой сторож преданный, куси, хватай презренных!",0,142],["p","Пес, верный страж текста, отвечал:"],["v","Нет, госпожа, не стану я кусать людей смиренных!",0,143],["v","Я столько лет и месяцев тебе служил голодный.",0,144],["v","Они меня насытили. Твои слова бесплодны.",0,145],["p","<span class=\"ch\" data-ch=\"creonta\">Креонта</span> кричала сообразно тексту:"],["v","Закройте, раздавите их, железные Ворота!",0,146],["p","Ворота отвечали по тексту:"],["v","Ты просишь нашей помощи: напрасная забота!",0,147],["v","Мы столько лет и месяцев, скорбя, ржавели. Жиром",0,148],["v","Нас эти люди смазали. Пускай уходят с миром.",0,149],["p","Забавно было видеть изумление <span class=\"ch\" data-ch=\"tartaglia\">Тартальи</span> и <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> перед таким обилием поэтов. Они были ошеломлены, слыша, как Пекарка, Веревка, Пес и Ворота разговаривают между собой мартеллианскими стихами. Они благодарили эти вещи за их милосердие.","pol"],["p","Зрители были чрезвычайно довольны этой чудесной ребяческой новинкой, и, признаюсь, я смеялся и сам, чувствуя, как душа принуждена радоваться детским образам, возвращавшим меня во времена моего младенчества."],["p","Выходила великанша <span class=\"ch\" data-ch=\"creonta\">Креонта</span>. Она была громадного роста и носила платье «андриенну».<a class=\"nr\" href=\"#n-n10\" data-n=\"n10\" aria-label=\"Примечание 10\">10</a> При ее ужасном появлении <span class=\"ch\" data-ch=\"tartaglia\">Тарталья</span> и <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> обращались в бегство."],["p","<span class=\"ch\" data-ch=\"creonta\">Креонта</span> с жестами отчаяния произносила следующие отчаянные мартеллианские стихи, не переставая взывать к Пиндару, которого синьор Кьяри считал своим собратом:","pol"],["v","О слуги вероломные, Веревка, Пес, Ворота,",0,150],["v","Пекарка нечестивая, о дщерь Искариота!<a class=\"nr\" href=\"#n-n11\" data-n=\"n11\" aria-label=\"Примечание 11\">11</a>",0,151],["v","О Апельсины сладкие! Мне вас лишиться надо!",0,152],["v","О Апельсины милые, мой свет, моя отрада!",0,153],["v","Я лопаюсь от ярости! В груди своей я чую",0,154],["v","Стихии, Солнце, Хаос весь и Радугу цветную.",0,155],["v","Нет, дольше жить не в силах я! Зевеса гром летучий,",0,156],["v","От темени до щиколок разбей меня из тучи!",0,157],["v","Кто мне поможет, дьяволы, кто мук прервет теченье?",0,158],["v","Вот дружеская молния: в ней смерть и утешенье.",0,159],["p","Никакая преувеличенная пародия не сможет лучше объяснить чувства и стиль синьора Кьяри, чем этот последний стих. Падала молния, которая испепеляла великаншу. На этом кончалось второе действие, заслужившее у публики еще больше аплодисментов, чем первое. Моя смелость начинала уже становиться менее преступной.","pol"],["act","Действие третье","a3","III"],["p","Сцена изображала место вблизи озера, в котором обитала фея <span class=\"ch\" data-ch=\"morgana\">Моргана</span>."],["p","Виднелось огромное дерево, а под ним большой камень в форме скамьи. По всей местности были разбросаны разные камни."],["p","Смеральдина, говорившая на итальянизированном турецком языке, стояла на берегу озера, ожидая приказаний феи. Выйдя из терпения, она звала ее."],["p","Из озера выходила фея <span class=\"ch\" data-ch=\"morgana\">Моргана</span>. Она рассказывала, что была в аду и там узнала, что <span class=\"ch\" data-ch=\"tartaglia\">Тарталья</span> и <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> с помощью <span class=\"ch\" data-ch=\"chelio\">Челио</span> победоносно шествуют, подталкиваемые мехами дьявола, с тремя Апельсинами в руках. <span class=\"ch\" data-ch=\"smeraldina\">Смеральдина</span> упрекала ее за невежество в магии: она была в бешенстве. <span class=\"ch\" data-ch=\"morgana\">Моргана</span> советовала ей не выходить из себя. Благодаря подстроенной ею хитрости <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> прибудет сюда отдельно от принца. Волшебный голод и жажда будут мучить его, и так как у него с собой три Апельсина, произойдут важные события. Она передавала арапке <span class=\"ch\" data-ch=\"smeraldina\">Смеральдине</span> две дьявольские шпильки. Говорила, что она увидит под деревом прекрасную девушку, сидящую на камне. Это будет жена, избранная <span class=\"ch\" data-ch=\"tartaglia\">Тартальей</span>. Пускай она постарается искусно воткнуть ей в волосы одну из шпилек. Тогда девушка превратится в голубку. Сама же <span class=\"ch\" data-ch=\"smeraldina\">Смеральдина</span> должна сесть на камень вместо этой девушки. <span class=\"ch\" data-ch=\"tartaglia\">Тарталья</span> женится на ней, и она станет королевой. Ночью, когда она будет спать с мужем, пускай она воткнет ему в волосы вторую шпильку; он превратится в животное, и таким образом трон останется свободным для <span class=\"ch\" data-ch=\"leandro\">Леандро</span> и <span class=\"ch\" data-ch=\"clarice\">Клариче</span>. Арапка находила в этом предприятии некоторые трудности, в особенности то, что ее хорошо знают при дворе. Волшебное искусство <span class=\"ch\" data-ch=\"morgana\">Морганы</span>, как и следовало ожидать, устраняло все препятствия. Она уводила с собой <span class=\"ch\" data-ch=\"smeraldina\">Смеральдину</span>, чтобы научить ее, как действовать, так как видела, что приближается <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span>, гонимый адским ветром."],["p","Выбегал <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> с поддувавшим на него дьяволом и с тремя Апельсинами в мешке. Дьявол исчезал. <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> рассказывал, что принц упал неподалеку вследствие стремительности их бега; теперь он хочет его подождать. Он садился. Он начинал чувствовать необыкновенный голод и жажду."],["p","Решал съесть один из трех Апельсинов. Испытывал угрызения совести, разыгрывал трагическую сцену. Наконец, ослепленный, измученный невероятным голодом, он решался принести великую жертву. Полагал, что можно возместить убытки двумя сольдо. Разрезал один из Апельсинов. О, чудо! Из него выходила девушка, одетая в белое, которая, точно следуя тексту сказки, говорила:"],["v","О, дай мне пить! О, горе мне! Сейчас умру! За что же?",0,160],["v","Умру от жажды, бедная! Скорей, мучитель! Боже!",0,161],["p","Она падала на землю, охваченная смертельным томлением. <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> забыл приказание <span class=\"ch\" data-ch=\"chelio\">Челио</span> разрезать Апельсины только около источника. Одуревший от голода и от необычайности всего случившегося с ним, он в отчаянии не замечал соседнего озера; ему приходил в голову только один выход: разрезать другой Апельсин, чтобы утолить его соком жажду умирающей девушки. Он тотчас же приступал к этому жестокому поступку, разрезал другой Апельсин, и вот из него появлялась другая прекрасная девушка со следующими словами на устах:"],["v","Увы, умру от жажды я! Дай пить, я умоляю!",0,162],["v","О боже, как я мучаюсь! Я в муках умираю.",0,163],["p","Она падала, как и первая. <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> приходил в сильнейшее беспокойство. Он был вне себя от отчаяния. Одна из девушек продолжала жалобным голосом:"],["v","Свирепый рок! Сейчас умру. Кончаюсь. Я скончалась.",0,164],["p","Она испускала дух. Другая девушка прибавляла:"],["v","Жестокий свет! Я в смертный час без помощи осталась.",0,165],["p","Она тоже испускала дух. <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> плакал, нежно с ними разговаривал."],["p","Он решал разрезать третий Апельсин, чтобы помочь им. Он уже был готов привести свое намерение в исполнение, как вдруг выходил разгневанный принц <span class=\"ch\" data-ch=\"tartaglia\">Тарталья</span> и грозил ему, <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> в ужасе убегал, оставив Апельсин."],["p","Изумление и размышления этого гротескового принца над корками двух разрезанных Апельсинов и над трупами двух девушек не поддаются описанию."],["p","Веселые маски импровизированной комедии при подобного рода обстоятельствах разыгрывают сцены таких милых глупостей, таких приятных шуток и ломанья, которые нельзя ни пером описать, ни превзойти в поэтических произведениях."],["p","После длинного и забавного монолога <span class=\"ch\" data-ch=\"tartaglia\">Тарталья</span> замечал двух проходивших мимо людей и приказывал им похоронить с почетом обеих девушек. Люди уносили их прочь."],["p","Принц обращался к третьему Апельсину. К его удивлению, он чрезвычайно вырос и стал похож на огромную тыкву."],["p","Он замечал вблизи озеро; следовательно, согласно указаниям <span class=\"ch\" data-ch=\"chelio\">Челио</span>, это было подходящее место. Он разрезал Апельсин своим мечом, и из него выходила высокая, красивая девушка, которая, следуя тексту этого серьезного сюжета, восклицала:"],["v","Ах, кто разрушил мой затвор! О небо, как я стражду!",0,166],["v","Чтоб не оплакивать меня, дай утолить мне жажду!",0,167],["p","И падала на землю."],["p","Принц понимал теперь смысл приказа <span class=\"ch\" data-ch=\"chelio\">Челио</span>. Он был в затруднении, так как у него не было ничего, чем он мог бы зачерпнуть воды. Обстоятельства заставили забыть о вежливости. Он снимал один из железных башмаков, бежал к озеру, наполнял его водой и, принеся извинение за несоответствующий сосуд, давал подкрепиться девушке, которая поднималась сильной и благодарила его за помощь."],["p","Она рассказывала, что она дочь Конкула, короля Антиподов,<a class=\"nr\" href=\"#n-n12\" data-n=\"n12\" aria-label=\"Примечание 12\">12</a> и что она была осуждена волшебством жестокой <span class=\"ch\" data-ch=\"creonta\">Креонты</span> вместе с двумя сестрами пребывать в кожуре Апельсина по причине столь же правдоподобной, сколь правдоподобен самый этот случай. Следовала шутливо-любовная сцена. Принц клялся, что женится на ней. Город находился вблизи. Принцесса не имела приличной одежды. Принц уговаривал ее подождать, сидя на камне под сенью дерева. Он обещал прийти за ней с богатыми одеждами в сопровождении всего двора. Порешив на этом, они расстались со вздохами."],["p","Выходила арапка <span class=\"ch\" data-ch=\"smeraldina\">Смеральдина</span>, изумленная всем, что она видела. Она замечала в воде озера отражение прекрасной девушки. Можно было не опасаться, что она не исполнит в точности всего, что предписывалось сказкой этой арапке. Она больше не говорила на итальянизированном турецком наречии."],["p","<span class=\"ch\" data-ch=\"morgana\">Моргана</span> впустила ей в язык тосканского дьявола, и она могла бросить вызов всем поэтам в правильности своей речи. Она обнаруживала молодую принцессу, которую звали <span class=\"ch\" data-ch=\"ninetta\">Нинеттой</span>. Она льстила ей, предлагала свои услуги, чтобы поправить ей головной убор, подходила к ней и предательски втыкала ей в голову одну из двух заколдованных шпилек. <span class=\"ch\" data-ch=\"ninetta\">Нинетта</span> превращалась в <span class=\"ch\" data-ch=\"ninetta\">Голубку</span> и улетала. <span class=\"ch\" data-ch=\"smeraldina\">Смеральдина</span> садилась на ее место, ожидая прибытия двора. Другой шпилькой она собиралась пронзить <span class=\"ch\" data-ch=\"tartaglia\">Тарталью</span> в эту ночь."],["p","Вся эта смесь чудесного и забавного, все ребячества этих сцен заставляли зрителей, которые с детских лет знали от нянек и бабушек содержание этой сказки, следить с большим вниманием за всеми перипетиями ее сюжета, и души их были увлечены смелой попыткой воспроизвести ее в театре."],["p","Под звуки марша появились <span class=\"ch\" data-ch=\"silvio\">Сильвио</span> — король Треф, принц <span class=\"ch\" data-ch=\"tartaglia\">Тарталья</span>, Леандро, Клариче, <span class=\"ch\" data-ch=\"brighella\">Бригелла</span> и весь двор, чтобы торжественно отвести в город принцессу-невесту. Видя вместо нее арапку, не узнанную благодаря колдовству <span class=\"ch\" data-ch=\"morgana\">Морганы</span>, принц приходил в ярость. Арапка клялась, что она — принцесса, оставленная здесь. Принц не мог не вызвать смеха своими стонами. <span class=\"ch\" data-ch=\"leandro\">Леандро</span>, <span class=\"ch\" data-ch=\"clarice\">Клариче</span> и <span class=\"ch\" data-ch=\"brighella\">Бригелла</span> радовались. Они понимали истинную причину происшедшего."],["p","Король Треф с важностью уговаривал сына сдержать свое слово и жениться на арапке. Он угрожал ему. Принц грустно соглашался, проделывая разные шутовские выходки. Раздавались звуки инструментов, и все общество направлялось ко двору, чтобы отпраздновать свадьбу."],["p","<span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> не пришел вместе с двором. Он получил от принца прощение своих грехов. Принц дал ему звание королевского повара.<a class=\"nr\" href=\"#n-n13\" data-n=\"n13\" aria-label=\"Примечание 13\">13</a> Он остался на кухне готовить свадебный пир."],["p","Следующая за уходом двора сцена была самой смелой в этой шутливой пародии. Представители партий синьоров Кьяри и Гольдони, находившиеся в театре и заметившие колкие остроты, делали всяческие попытки вызвать гневный шум в аудитории, но все их усилия были напрасными. Я уже сказал, что в лице <span class=\"ch\" data-ch=\"chelio\">Челио</span> я изобразил синьора Гольдони, а в лице <span class=\"ch\" data-ch=\"morgana\">Морганы</span> — синьора Кьяри. Первый был некоторое время адвокатом в венецианском суде, и его литературная манера отдавала стилем тех писаний, к которым привыкли адвокаты в этом почтенном трибунале. Синьор Кьяри хвастался пиндарическим и возвышенным стилем, но я должен сказать, с вашего позволения, что в семнадцатом веке не было у нас ни одного столь напыщенного и безрассудного писателя, который превзошел бы его невероятные ошибки.","pol"],["p","Возбужденные взаимной ненавистью и злобой, <span class=\"ch\" data-ch=\"chelio\">Челио</span> и <span class=\"ch\" data-ch=\"morgana\">Моргана</span>, встретившись, разыгрывали следующую сцену, которую я перепишу целиком, вместе с диалогом."],["p","Следует помнить, что если пародия не ударится в преувеличение, она никогда не достигнет желаемой цели. Поэтому надо снисходительно отнестись к капризу, родившемуся от веселого и шутливого ума, в основном как нельзя более дружественного к синьорам Кьяри и Гольдони.","pol"],["sp","<span class=\"ch\" data-ch=\"chelio\">Челио</span>"],["dir","выходя стремительно, <span class=\"ch\" data-ch=\"morgana\">Моргане</span>"],["p","Злодейка-фея, я узнал все твои обманы; но Плутон мне поможет. Подлая ведьма! Проклятая колдунья!","spk"],["sp","<span class=\"ch\" data-ch=\"morgana\">Моргана</span>"],["p","Что это за разговор, шарлатанский маг? Не задевай меня, а не то я задам тебе головомойку в мартеллианских стихах и заставлю тебя умереть от зевоты.","spk"],["sp","<span class=\"ch\" data-ch=\"chelio\">Челио</span>"],["p","Мне, дерзкая ведьма? Я отплачу тебе той же монетой! Вызываю тебя на поединок в мартеллианских стихах. Вот тебе:","spk"],["v","Отныне домогательством сочтутся беззаконным,",0,168],["v","Бесчестным, бездоказанным, защиты прав лишенным,",0,169],["v","Твои неосторожные и дерзкие деянья,",0,170],["v","Их вредные последствия, равно как волхвованья,",0,171],["v","И зло, всем в назидание, подвергнется клейменью,",0,172],["v","Искорененью полному, изгнанью, заточенью.",0,173],["sp","<span class=\"ch\" data-ch=\"morgana\">Моргана</span>"],["p","Вот скверные стихи! Теперь моя очередь, ничтожный маг.","spk"],["v","Скорее стрелы Фебовы, сверкающие златом,",0,174],["v","Презренным станут оловом или Восток Закатом,",0,175],["v","Скорей луна двурогая, чей свет прельщает очи,",0,176],["v","Небесное владычество уступит звездам ночи,",0,177],["v","Скорее реки дольные с их хрусталем певучим,",0,178],["v","Взмыв на Пегасе пламенном, вверх вознесутся к тучам,",0,179],["v","Чем пренебречь возможешь ты, Плутона раб негодный,",0,180],["v","Кормилом и ветрилами моей ладьи свободной!",0,181],["sp","<span class=\"ch\" data-ch=\"chelio\">Челио</span>"],["p","О надутая, как пузырь, колдунья! Подожди!","spk"],["v","Развязка воспоследует в ближайших же явленьях",0,182],["v","На точном основании статей о превращеньях.",0,183],["v","Нинетта, ныне горлица, разрушит чарованье",0,184],["v","И скоро в первобытное вернется состоянье.",0,185],["v","Засим, на основании статей о ряде следствий,",0,186],["v","<span class=\"ch\" data-ch=\"clarice\">Клариче</span> и <span class=\"ch\" data-ch=\"leandro\">Леандро</span> твой впадут в пучину бедствий,",0,187],["v","А <span class=\"ch\" data-ch=\"smeraldina\">Смеральдину</span> черную, ее злодейства ради,",0,188],["v","Истицу безнадежную, слегка поджарят сзади.",0,189],["sp","<span class=\"ch\" data-ch=\"morgana\">Моргана</span>"],["p","О глупый, глупый рифмоплет! Слушай меня, я тебя устрашу:","spk"],["v","На крыльях, воском спаянных, Икар, гордыни полный,",0,190],["v","Отважно к небу взносится, спускается на волны.",0,191],["v","Обременяют Оссою вершину Пелиона",0,192],["v","Титаны разъяренные, чтоб Зевса свергнуть с трона.",0,193],["v","Икары будут свергнуты в пучину океанов,",0,194],["v","И Громовержца молния испепелит титанов.",0,195],["v","<span class=\"ch\" data-ch=\"clarice\">Клариче</span> на престол взойдет, твоим не внемля пеням,",0,196],["v","А принц, как новый Актеон, окажется оленем.",0,197],["sp","<span class=\"ch\" data-ch=\"chelio\">Челио</span>"],["dir","в сторону"],["p","Она хочет осилить меня поэтическими преувеличениями. Если она думает загнать меня в мешок, она ошибается.","spk"],["v","Ввиду того, что речь твоя груба и неприлична,",0,198],["v","Ее незамедлительно опротестую лично.",0,199],["sp","<span class=\"ch\" data-ch=\"morgana\">Моргана</span>"],["v","Пусть ныне королевство Треф страною вольной будет!",0,200],["dir","Уходила."],["sp","<span class=\"ch\" data-ch=\"chelio\">Челио</span>"],["dir","кричал ей вслед"],["v","Я предъявляю встречный иск! Тебе платить присудят!",0,201],["dir","Уходил."],["p","Далее сцена изображала королевскую кухню. Никогда еще не было видано более жалкой королевской кухни, чем эта."],["p","Остальная часть представления была лишь окончанием сказки, представленной во всех подробностях, за которой зрители продолжали следить с неослабевающим вниманием."],["p","Пародия касалась теперь низостей и тривиальностей, а также пошлости некоторых характеров в произведениях обоих наших поэтов. Суть ее заключалась в невероятной скудости, неуместности и низменности.","pol"],["p","<span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> был занят насаживанием жаркого на вертел. В отчаянии он рассказывал, что, так как в этой кухне нет вращающегося вертела, ему пришлось самому поворачивать вертел. В это время на оконце появлялась <span class=\"ch\" data-ch=\"ninetta\">Голубка</span>; между ним и <span class=\"ch\" data-ch=\"ninetta\">Голубкой</span> происходил следующий разговор. (Эти слова взяты из текста сказки.)"],["p","<span class=\"ch\" data-ch=\"ninetta\">Голубка</span> говорила ему: «Здравствуй, повар!» Он ей отвечал: «Здравствуй, белая <span class=\"ch\" data-ch=\"ninetta\">Голубка</span>!» <span class=\"ch\" data-ch=\"ninetta\">Голубка</span> добавляла: «Я молю небо, чтобы ты заснул и жаркое сгорело; пускай арапка, противная тварь, не будет в состоянии его есть». После этого на него нападал чудесный сон, он засыпал, а жаркое превращалось в уголья. Так происходило два раза. Два жарких сгорели."],["p","Он поспешно ставил на огонь третье жаркое. Появлялась <span class=\"ch\" data-ch=\"ninetta\">Голубка</span>, и повторялся тот же разговор. Волшебный сон опять нападал на <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span>. Этот милый персонаж делал все усилия, чтобы не заснуть: его шутки, свойственные театру,<a class=\"nr\" href=\"#n-n14\" data-n=\"n14\" aria-label=\"Примечание 14\">14</a> были чрезвычайно забавны. Он засыпал. Огонь обращал в уголья и третье жаркое."],["p","Пускай спросят у публики, почему эта сцена имела такой исключительный успех."],["p","Появлялся с криком <span class=\"ch\" data-ch=\"pantalone\">Панталоне</span> и будил <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span>. Он говорил, что король разгневан, потому что уже съедены суп, вареное мясо и печенка, а жаркого все нет. Да здравствует смелость поэта! Тем самым были превзойдены драки из-за тыкв кьоджинских женщин синьора Гольдони. <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> рассказывал историю с <span class=\"ch\" data-ch=\"ninetta\">Голубкой</span>. <span class=\"ch\" data-ch=\"pantalone\">Панталоне</span> не верил этим чудесам. Появлялась <span class=\"ch\" data-ch=\"ninetta\">Голубка</span> и повторяла волшебные слова. <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> готов был снова впасть в оцепенение. Оба эти персонажа начинали гоняться за <span class=\"ch\" data-ch=\"ninetta\">Голубкой</span>, которая порхала по кухне.","pol"],["p","Эта погоня живо интересовала публику. <span class=\"ch\" data-ch=\"ninetta\">Голубку</span> ловили, сажали на стол, гладили. Нащупывали маленькую шпилечку на ее голове; это была волшебная шпилька. <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> вытаскивал ее, и <span class=\"ch\" data-ch=\"ninetta\">Голубка</span> тотчас же превращалась в принцессу <span class=\"ch\" data-ch=\"ninetta\">Нинетту</span>."],["p","Изумление было очень велико. Появлялся его величество король Треф, который с монаршей величественностью и со скипетром в руке грозил <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> за опоздание жаркого и за стыд, который такой человек, как он, должен был испытать перед приглашенными."],["p","Приходил принц <span class=\"ch\" data-ch=\"tartaglia\">Тарталья</span>, узнавал свою <span class=\"ch\" data-ch=\"ninetta\">Нинетту</span>. Он был вне себя от радости. <span class=\"ch\" data-ch=\"ninetta\">Нинетта</span> рассказывала вкратце свои приключения; король оставался в изумлении. Он видел появление в кухне вслед за ним арапки и всего остального двора. Приняв чрезвычайно гордую осанку, король приказывал принцу и принцессе выйти в судомойню и, избрав себе в качестве трона очаг, садился на него со всем королевским достоинством. Появлялись арапка <span class=\"ch\" data-ch=\"smeraldina\">Смеральдина</span> и весь двор. Король, точно следуя сказке, описывал происшедшее и спрашивал, какого наказания заслуживают виновные. Каждый в смущении высказывал свое мнение."],["p","Король в ярости приговаривал арапку <span class=\"ch\" data-ch=\"smeraldina\">Смеральдину</span> к сожжению."],["p","Появлялся маг <span class=\"ch\" data-ch=\"chelio\">Челио</span>. Он разоблачал вину <span class=\"ch\" data-ch=\"clarice\">Клариче</span>, <span class=\"ch\" data-ch=\"leandro\">Леандро</span> и <span class=\"ch\" data-ch=\"brighella\">Бригеллы</span>. Их приговаривали к жестокому изгнанию. Вызывали из судомойни принца с его нареченной. Все ликовали."],["p","<span class=\"ch\" data-ch=\"chelio\">Челио</span> уговаривал <span class=\"ch\" data-ch=\"truffaldino\">Труффальдино</span> держать дьявольские мартеллианские стихи подальше от королевских кастрюль и почаще заставлять смеяться своих государей."],["p","Сказка кончалась обычным финалом, который знает наизусть каждый ребенок: свадьбой, тертым табаком в компоте, бритыми крысами, ободранными котами и т. п."],["p","А так как господа журналисты того времени без конца расхваливали в своих листках всякую новую пьесу, представленную синьором Гольдони, то не было забыто и горячее обращение к публике с просьбой принять на себя посредничество между актерами и господами газетчиками в защиту доброй славы этого таинственного вздора.","pol"],["p","Я не был виноват. Любезная публика требовала несколько вечеров подряд повторения этой фантастической пародии. Стечение народа было огромно. Труппа Сакки могла наконец свободно вздохнуть."],["p","Мне придется в дальнейшем указать на большие последствия, которые произошли от такого легкомысленного начала.<a class=\"nr\" href=\"#n-n15\" data-n=\"n15\" aria-label=\"Примечание 15\">15</a> Тот, кто знает Италию и не является по духу энтузиастом французской деликатности, не будет судить мою пародию, сравнивая ее с пародиями этого народа."],["h1","Примечания","notes"],["note","n1"],["note","n2"],["note","n3"],["note","n4"],["note","n5"],["note","n6"],["note","n7"],["note","n8"],["note","n9"],["note","n10"],["note","n11"],["note","n12"],["note","n13"],["note","n14"],["note","n15"]],"n":{"n1":["Эпиграф","Октавы взяты из «Морганте» (1483) Луиджи Пульчи (1432–1484) — пародийно-шутливой рыцарской поэмы, одной из любимых книг Гоцци. Поэт сравнивает себя с великаном Морганте, который крушит противников палицей; Гоцци примеряет эту роль на себя в войне с Кьяри и Гольдони. <i class=\"nsrc\">[Комм.]</i>"],"n2":["…труппу актеров импровизированной комедии Сакки","Для труппы Антонио Сакки Гоцци написал все свои десять сказок. Полный её состав, как сказано в комментарии, установить сейчас невозможно. <i class=\"nsrc\">[Комм.]</i>"],"n3":["«Кухарки», «Кьоджинские перепалки»","Народные комедии Гольдони на венецианском диалекте; в обеих ссорятся и бранятся простые женщины. Эти перебранки Гоцци и передразнивает в сцене у фонтанов. <i class=\"nsrc\">[Комм.]</i>"],"n4":["Король Треф","В подлиннике — «король Чаш». Итальянская колода делится на масти Чаши, Деньги, Мечи и Палицы; для игры в тарок добавлялась пятая — Тароки (их фигуры появятся в сказке «Зелёная Птичка»). Старшие карты каждой масти — туз, король, всадник и валет; отсюда и Леандро — «валет Треф». <i class=\"nsrc\">[Комм.]</i>"],"n5":["…написаны мартеллианскими стихами","Мартеллианский стих — длинная парно рифмованная строка из двух полустиший (названа по имени поэта П. Я. Мартелло); у Лозинского она передана четырнадцатисложником с цезурой. Гоцци сильно преувеличивает: по подсчёту комментатора, Гольдони писал этим размером только в годы работы в театре Сан-Лука (1753–1762) — 29 пьес при 137 комедиях, 5 трагедиях и 16 трагикомедиях. <i class=\"nsrc\">[Комм.]</i>"],"n6":["Арапка Смеральдина","В подлиннике Смеральдина — <i>mora</i>: в старину это слово значило и «мавританка», и «негритянка». Переводчик передал его словом «арапка», тем более что в тексте подчёркнута её чернота. <i class=\"nsrc\">[Комм.]</i>"],"n7":["Плутон — властитель Тартара, и Пиндар, вверх парящий","В одной строке соединены мифический бог подземного царства и реальный поэт — греческий лирик Пиндар (V в. до н. э.). Такая смесь, по словам комментатора, «ярко характеризует» безвкусный стиль Кьяри, который называл Пиндара своим собратом. <i class=\"nsrc\">[Комм.]</i>"],"n8":["Бригелла предлагал импровизированную комедию масок…","Роль Бригеллы двойственна: он помогает злодеям Клариче и Леандро, но в споре о театре защищает комедию дель арте теми же доводами, что и сам Гоцци. Его монолог о горькой судьбе актёров Сакки встречали «бурными аплодисментами». <i class=\"nsrc\">[Комм.]</i>"],"n9":["В своих драмах, заимствованных из «Энеиды»…","В 1760 г. антрепренёр Медебак, у которого служил Кьяри, снял театр Сан-Джованни Кризостомо, приспособленный для оперных эффектов. Кьяри тут же написал «Троянскую тетралогию», где действовали Венера, Сивилла, Харон и Вулкан с циклопами. <i class=\"nsrc\">[Комм.]</i>"],"n10":["…носила платье «андриенну»","Андриенна — просторное платье с длинной юбкой, скрадывающее талию. Его придумала актриса Данкур, надевшая его, будучи беременной, для главной роли в комедии Барона «Андриенна»; мода пришла из Франции и в Италию. <i class=\"nsrc\">[Комм.]</i>"],"n11":["…о дщерь Искариота!","«О дочь Иуды», то есть предательница: Иуда Искариот предал Христа. <i class=\"nsrc\">[Комм.]</i>"],"n12":["…дочь Конкула, короля Антиподов","Антиподы — жители противоположной точки земного шара; королевство Конкула находится, значит, «на другом конце света». <i class=\"nsrc\">[Комм.]</i>"],"n13":["Принц дал ему звание королевского повара","Повышение по характеру: Труффальдино — великий любитель и мастер поесть. <i class=\"nsrc\">[Комм.]</i>"],"n14":["…шутки, свойственные театру","Так в комедии дель арте называли пантомимические и мимические номера — лацци. Их разыгрывали прежде всего слуги-дзанни, иногда вместе со стариками (Панталоне, Доктором, Капитаном); с сюжетом они почти не связаны и были самостоятельными вставными номерами. <i class=\"nsrc\">[Комм.]</i>"],"n15":["…большие последствия, которые произошли от такого легкомысленного начала","Гоцци имеет в виду, что из пародийной сказки, задуманной как шутка, вырос серьёзный жанр сказочной трагикомедии — «Ворон», «Король-олень», «Турандот» и другие фьябы. <i class=\"nsrc\">[Комм.]</i>"]},"mainEnd":383,"c":[{"id":"tartaglia","name":"Тарталья","role":"Наследный принц королевства Треф","intro":"Десять лет болен ипохондрией; врачи сказали, что спасти его может только смех.","arc":"Шутовской принц-ипохондрик, которого Гоцци сделал героем рыцарского поиска. Смех исцеляет его, но проклятие Морганы тут же даёт новую одержимость — любовь к трём апельсинам. Он грозит отцу, надевает железные башмаки, крадёт апельсины у Креонты, освобождает Нинетту, а потом покорно соглашается жениться на подменной арапке — пока Голубка не возвращает ему невесту.","st":[{"i":155,"p":41,"l":"Действие первое","t":"Больной","d":"Жалуется на болезнь среди склянок и мазей; Труффальдино не может его рассмешить.","c":"","k":false},{"i":166,"p":43,"l":"Действие первое","t":"Смех","d":"Видит, как старушонка падает, задрав ноги, хохочет и разом выздоравливает.","c":"Лекарство масок победило.","k":true},{"i":180,"p":47,"l":"Действие первое","t":"Проклятие","d":"Моргана проклинает его, и он воспламеняется любовью к трём апельсинам.","c":"Новая мания вместо старой.","k":true},{"i":188,"p":49,"l":"Действие второе","t":"Железные башмаки","d":"Против воли отца отправляется в путь с Труффальдино-оруженосцем.","c":"","k":false},{"i":230,"p":60,"l":"Действие второе","t":"Похищение","d":"Пробирается в замок Креонты и выносит три апельсина.","c":"","k":true},{"i":295,"p":77,"l":"Действие третье","t":"Нинетта","d":"У озера разрезает третий апельсин, поит принцессу водой из железного башмака и клянётся жениться.","c":"","k":true},{"i":305,"p":80,"l":"Действие третье","t":"Подмена","d":"Вместо невесты находит арапку и по приказу отца соглашается на свадьбу.","c":"","k":false},{"i":375,"p":98,"l":"Действие третье","t":"Свадьба","d":"Узнаёт расколдованную Нинетту.","c":"","k":true}]},{"id":"truffaldino","name":"Труффальдино","role":"Шут, посланный ко двору магом Челио","intro":"«Настоящий рецепт против ипохондрии».","arc":"Труффальдино — главный довод Гоцци в споре о театре: там, где у поэтов скука мартеллианских стихов, у него импровизация и лацци. Он смешит принца, сопровождает его оруженосцем, от голода губит двух принцесс из апельсинов и, став поваром, трижды проспит жаркое.","st":[{"i":156,"p":41,"l":"Действие первое","t":"Лекарь","d":"Исследует «больного» и находит в нём непереваренные мартеллианские стихи.","c":"","k":false},{"i":165,"p":43,"l":"Действие первое","t":"Победа","d":"Бранит старушонку-Моргану, она падает — принц смеётся.","c":"","k":true},{"i":185,"p":48,"l":"Действие второе","t":"Оруженосец","d":"Вооружается вместе с принцем.","c":"","k":false},{"i":279,"p":73,"l":"Действие третье","t":"Голод","d":"Режет апельсины вдали от воды; две принцессы умирают от жажды.","c":"","k":true},{"i":306,"p":80,"l":"Действие третье","t":"Повар","d":"Прощён и назначен поваром.","c":"","k":false},{"i":373,"p":98,"l":"Действие третье","t":"Шпилька","d":"Вынимает из головы Голубки волшебную шпильку.","c":"Развязка — руками маски.","k":true}]},{"id":"chelio","name":"Челио","role":"Маг, покровитель короля Треф; карикатура на Гольдони","intro":"Посылает ко двору Труффальдино.","arc":"Гоцци сам объясняет: Челио — Гольдони, враждующая с ним Моргана — Кьяри; их вражда — аллегория театральных войн Венеции. Челио помогает принцу советами из детской сказки и вызывает Моргану на поединок мартеллианскими стихами, говоря языком адвокатских бумаг (Гольдони был адвокатом).","st":[{"i":152,"p":40,"l":"Действие первое","t":"Покровитель","d":"Через Бригеллу становится известно, что Труффальдино послан им.","c":"","k":false},{"i":194,"p":51,"l":"Действие второе","t":"Заклинание","d":"Вызывает Фарфарелло и спорит с ним, на каком языке говорить магам.","c":"","k":false},{"i":221,"p":58,"l":"Действие второе","t":"Советы","d":"Даёт принцу мазь, хлеб и веник и учит резать апельсины только у воды.","c":"","k":true},{"i":308,"p":81,"l":"Действие третье","t":"Поединок","d":"Сражается с Морганой стихами.","c":"Центральная сцена-пародия.","k":true},{"i":377,"p":99,"l":"Действие третье","t":"Развязка","d":"Разоблачает заговорщиков.","c":"","k":false}]},{"id":"morgana","name":"Моргана","role":"Фея, враг короля Треф; карикатура на Кьяри","intro":"Проиграла много денег, ставя на карту короля Треф.","arc":"Покровительница заговорщиков: даёт Леандро «грамоты в мартеллианских стихах», проклятием насылает на принца любовь к апельсинам, руками Смеральдины превращает Нинетту в голубку. Её стиль — пародия на пиндарическую высокопарность Кьяри.","st":[{"i":160,"p":42,"l":"Действие первое","t":"Старушонка","d":"Является на праздник, чтобы погубить принца.","c":"","k":false},{"i":165,"p":43,"l":"Действие первое","t":"Падение","d":"Падает у фонтана — и тем исцеляет принца.","c":"","k":false},{"i":180,"p":47,"l":"Действие первое","t":"Проклятие","d":"Произносит проклятие «в стиле Кьяри».","c":"","k":true},{"i":277,"p":73,"l":"Действие третье","t":"Шпильки","d":"Даёт Смеральдине шпильки для превращений.","c":"","k":false},{"i":308,"p":81,"l":"Действие третье","t":"Поединок","d":"Отвечает Челио пиндарическими стихами.","c":"","k":true}]},{"id":"silvio","name":"Сильвио","role":"Король Треф","intro":"Монарх в одеждах карточного короля, оплакивающий больного сына.","arc":"Комический король-отец: плачет навзрыд, «забыв о своем королевском величии», в патетическом тоне отговаривает сына от похода, падает в обморок, объявляет траур. В финале, усевшись на кухонный очаг как на трон, вершит суд «точно следуя сказке».","st":[{"i":148,"p":39,"l":"Действие первое","t":"Горе отца","d":"Жалуется на болезнь сына и соглашается устроить празднества.","c":"","k":false},{"i":188,"p":49,"l":"Действие второе","t":"Прощание","d":"Отговаривает сына от похода и слышит от него угрозы.","c":"","k":false},{"i":190,"p":50,"l":"Действие второе","t":"Траур","d":"Падает в обморок и велит двору облачиться в траур.","c":"","k":false},{"i":305,"p":80,"l":"Действие третье","t":"Свадьба с арапкой","d":"Заставляет принца жениться на подменной невесте.","c":"","k":false},{"i":375,"p":98,"l":"Действие третье","t":"Суд на кухне","d":"Судит виновных и приговаривает арапку к сожжению.","c":"","k":true}]},{"id":"clarice","name":"Клариче","role":"Принцесса, племянница короля","intro":"Будущая наследница престола, «своевольная, странная и жестокая».","arc":"Пародия на героинь Кьяри: требует трагедий, где бросаются из окон, мечтает командовать войсками и заколоть влюблённого врага. Вместе с Леандро ждёт смерти Тартальи и в финале изгнана.","st":[{"i":151,"p":40,"l":"Действие первое","t":"Заговор","d":"Бранит Леандро за медлительность в умерщвлении принца.","c":"","k":true},{"i":154,"p":40,"l":"Действие первое","t":"Мышьяк или пуля","d":"Предлагает способы погубить Труффальдино.","c":"","k":false},{"i":191,"p":50,"l":"Действие второе","t":"Планы","d":"Заранее выговаривает себе власть над войском и должностями.","c":"","k":false},{"i":192,"p":50,"l":"Действие второе","t":"Спор о театре","d":"Выбирает трагедии в духе Кьяри.","c":"","k":false},{"i":377,"p":99,"l":"Действие третье","t":"Изгнание","d":"Разоблачена Челио и изгнана.","c":"","k":true}]},{"id":"leandro","name":"Леандро","role":"Валет Треф, первый министр","intro":"Одет, как фигура игральной карты; надеется стать королём.","arc":"Министр-предатель, подопечный Морганы: травит принца «мартеллианскими стихами в хлебе», нарочно наряжает народ в мрачные маски, в споре о театре выбирает комедии характеров, то есть Гольдони.","st":[{"i":149,"p":39,"l":"Действие первое","t":"Под подозрением","d":"Отговаривает короля от праздников; Панталоне подозревает измену.","c":"","k":false},{"i":151,"p":40,"l":"Действие первое","t":"Грамоты в хлебе","d":"Объясняет Клариче, как медленно губит принца.","c":"","k":true},{"i":192,"p":50,"l":"Действие второе","t":"Спор о театре","d":"Стоит за комедии Гольдони.","c":"","k":false},{"i":377,"p":99,"l":"Действие третье","t":"Изгнание","d":"Изгнан вместе с Клариче.","c":"","k":true}]},{"id":"smeraldina","name":"Смеральдина","role":"Арапка, служанка, посредница между Леандро и Морганой","intro":"Говорит на «итальянизированном турецком».","arc":"Посредница злодеев. У озера Моргана вселяет ей в язык «тосканского дьявола», и она начинает говорить безупречно; шпилькой превращает Нинетту в голубку и садится на её место. Король приговаривает её к сожжению.","st":[{"i":151,"p":40,"l":"Действие первое","t":"Посредница","d":"Связывает Леандро с Морганой.","c":"","k":false},{"i":276,"p":72,"l":"Действие третье","t":"У озера","d":"Получает от Морганы шпильки и наставления.","c":"","k":false},{"i":302,"p":79,"l":"Действие третье","t":"Подмена","d":"Превращает Нинетту в голубку и занимает её место.","c":"","k":true},{"i":376,"p":98,"l":"Действие третье","t":"Приговор","d":"Приговорена к сожжению.","c":"","k":true}]},{"id":"ninetta","name":"Нинетта","role":"Дочь Конкула, короля Антиподов; принцесса из третьего апельсина","intro":"Заколдована Креонтой вместе с сёстрами и заключена в кожуру апельсина.","arc":"Единственная выжившая из трёх сестёр. Превращённая в голубку, она мстит подменной невесте, трижды усыпляя повара, — и снова становится принцессой, когда Труффальдино вынимает шпильку.","st":[{"i":295,"p":77,"l":"Действие третье","t":"Из апельсина","d":"Выходит из третьего апельсина и едва не умирает от жажды.","c":"","k":true},{"i":302,"p":79,"l":"Действие третье","t":"Голубка","d":"Смеральдина превращает её в голубку.","c":"","k":true},{"i":369,"p":97,"l":"Действие третье","t":"На кухне","d":"Усыпляет повара, и жаркое трижды сгорает.","c":"","k":false},{"i":373,"p":98,"l":"Действие третье","t":"Возвращение","d":"Снова становится принцессой.","c":"","k":true}]},{"id":"pantalone","name":"Панталоне","role":"Придворный, советник короля","intro":"Насмешник над врачами и знаток шарлатанских «секретов».","arc":"Подаёт королю спасительный совет — устроить празднества и пустить к принцу Труффальдино; первым подозревает Леандро; в финале будит заснувшего повара и вместе с ним ловит Голубку.","st":[{"i":148,"p":39,"l":"Действие первое","t":"Совет","d":"Советует устроить празднества и позвать Труффальдино.","c":"","k":true},{"i":183,"p":48,"l":"Действие второе","t":"Железные башмаки","d":"Просит у короля железные башмаки для принца.","c":"","k":false},{"i":372,"p":97,"l":"Действие третье","t":"На кухне","d":"Будит Труффальдино и гоняется за Голубкой.","c":"","k":false}]},{"id":"brighella","name":"Бригелла","role":"Гонец Леандро","intro":"Служит заговорщикам.","arc":"Двойная роль: он помогает злодеям, но в споре о театре защищает комедию масок и произносит патетическую речь о судьбе труппы Сакки (см. примеч. 8).","st":[{"i":152,"p":40,"l":"Действие первое","t":"Гонец","d":"Сообщает, что Труффальдино послан магом Челио.","c":"","k":false},{"i":192,"p":50,"l":"Действие второе","t":"Спор о театре","d":"Защищает импровизированную комедию масок.","c":"","k":true},{"i":193,"p":51,"l":"Действие второе","t":"Речь об актёрах","d":"Оплакивает притесняемых актёров.","c":"","k":false}]},{"id":"creonta","name":"Креонта","role":"Великанша-волшебница, хранительница трёх апельсинов","intro":"Живёт в замке за две тысячи миль; носит платье «андриенну».","arc":"Её слуги — Ворота, Пес, Веревка и Пекарка — отказываются ей повиноваться, потому что пришельцы обошлись с ними лучше хозяйки. В отчаянии она взывает к молнии и гибнет.","st":[{"i":231,"p":60,"l":"Действие второе","t":"Зов","d":"Тщетно приказывает слугам задержать похитителей.","c":"","k":true},{"i":260,"p":68,"l":"Действие второе","t":"Отчаяние","d":"Произносит «отчаянные мартеллианские стихи».","c":"","k":false},{"i":272,"p":71,"l":"Действие второе","t":"Гибель","d":"Молния испепеляет её.","c":"","k":true}]}]};
